#!/usr/bin/env python3
# Single node: exposes a capture service, then continually publishes the merged cloud.
#
# Usage:
#   python3 multiview_node.py
#   python3 multiview_node.py --config config/views.yaml --sim --settle 3.0
#
# Trigger a capture + merge:
#   ros2 service call /multiview/capture std_srvs/srv/Trigger
#
# Published (every 1 s, latched to the most recent successful capture):
#   /multiview/merged, /multiview/view_0 ... /multiview/view_{n-1}
#
# The first view is captured at the current robot position.
# Subsequent views are generated by applying random perturbations relative
# to the previous viewpoint. Views are then outlier-filtered, ICP-refined
# against view 0 and merged.

import argparse
import os
import sys
import threading
import time
from datetime import datetime

import numpy as np
import rclpy
import yaml

from pcl_python_merlab import PointCloud

from rclpy.callback_groups import MutuallyExclusiveCallbackGroup
from rclpy.duration import Duration
from rclpy.executors import MultiThreadedExecutor
from rclpy.node import Node
from rclpy.qos import QoSProfile, ReliabilityPolicy
from rclpy.time import Time

from sensor_msgs.msg import PointCloud2
from std_srvs.srv import Trigger
from tf2_ros import Buffer, TransformException, TransformListener

from helpers.geometry import (
    apply_transform,
    crop_box,
    load_cloud,
    rotation_angle_deg,
    save_cloud,
    transform_to_matrix,
)
from helpers.icp import alignment_error, icp_point_to_plane
from helpers.robot_motion import ArmMover
from helpers.ros_clouds import msg_to_numpy, numpy_to_msg
from ament_index_python.packages import get_package_share_directory

from common_interfaces_merlab.srv import SendPose

HERE = os.path.dirname(os.path.abspath(__file__))
CONFIG_DIR = os.path.join(
    get_package_share_directory('robot_sim'),
    'config'
)

RELIABLE_QOS = QoSProfile(
    reliability=ReliabilityPolicy.RELIABLE,
    depth=10,
)

MAX_CORRECTION_M = 0.02
MAX_CORRECTION_DEG = 6.0
MIN_FITNESS = 0.3
OUTLIER_NEIGHBORS = 20
OUTLIER_STDDEV = 2.0


# ----------------------------------------------------------------------------
# Merge helpers (from merge_views.py)
# ----------------------------------------------------------------------------

def remove_outliers(points):
    if len(points) <= OUTLIER_NEIGHBORS:
        return points
    return PointCloud(points).statistical_outlier_removal(
        mean_k=OUTLIER_NEIGHBORS, stddev_multiplier=OUTLIER_STDDEV).xyz


# ICP
def refine_with_icp(source, target, voxel, max_distance):
    src_ds = PointCloud(source).voxel_grid(leaf_size=voxel).xyz
    tgt_ds = PointCloud(target).voxel_grid(leaf_size=voxel).xyz
    fitness0, rmse0 = alignment_error(src_ds, tgt_ds, max_distance)
    T = np.eye(4)
    for radius in (4 * max_distance, 2 * max_distance, max_distance):
        moved = PointCloud(src_ds).transform(T).xyz
        T_step, fitness, rmse = icp_point_to_plane(moved, tgt_ds, max_distance=radius)
        T = T_step @ T
    moved = PointCloud(src_ds).transform(T).xyz
    fitness, rmse = alignment_error(moved, tgt_ds, max_distance)
    shift_mm, angle = np.linalg.norm(T[:3, 3]) * 1000, rotation_angle_deg(T[:3, :3])
    report = (f'overlap {fitness0:.0%} -> {fitness:.0%}, RMS {rmse0 * 1000:.1f} -> {rmse * 1000:.1f} mm, '
              f'correction {shift_mm:.1f} mm / {angle:.2f} deg')
    if shift_mm > MAX_CORRECTION_M * 1000 or angle > MAX_CORRECTION_DEG or fitness < MIN_FITNESS:
        return np.eye(4), report + '  -> REJECTED, keeping TF-only alignment'
    return T, report


# concatenate + voxel-downsample
def merge(views, voxel):
    cloud = PointCloud(views[0])
    for points in views[1:]:
        cloud = cloud.concatenate(PointCloud(points))
    return cloud.voxel_grid(leaf_size=voxel).xyz


# ----------------------------------------------------------------------------
# Perturbation helpers (from capture_views.py)
# ----------------------------------------------------------------------------

def euler_to_quat(roll, pitch, yaw):
    """Roll/pitch/yaw (radians) -> quaternion [x, y, z, w]."""
    cr, sr = np.cos(roll / 2), np.sin(roll / 2)
    cp, sp = np.cos(pitch / 2), np.sin(pitch / 2)
    cy, sy = np.cos(yaw / 2), np.sin(yaw / 2)

    return np.array([
        sr * cp * cy - cr * sp * sy,
        cr * sp * cy + sr * cp * sy,
        cr * cp * sy - sr * sp * cy,
        cr * cp * cy + sr * sp * sy,
    ])


def quat_multiply(q1, q2):
    """Hamilton product q1 * q2, both [x, y, z, w]."""
    x1, y1, z1, w1 = q1
    x2, y2, z2, w2 = q2

    q = np.array([
        w1 * x2 + x1 * w2 + y1 * z2 - z1 * y2,
        w1 * y2 - x1 * z2 + y1 * w2 + z1 * x2,
        w1 * z2 + x1 * y2 - y1 * x2 + z1 * w2,
        w1 * w2 - x1 * x2 - y1 * y2 - z1 * z2,
    ])

    return q / np.linalg.norm(q)


def generate_perturbation(cfg):
    """
    Generate a random translational + angular perturbation.

    Each axis is independently sampled from its configured range.
    Translation is in meters; angular_perturbation is in degrees.
    Returns (delta_xyz, delta_quat, delta_rpy_deg).
    """

    mag = cfg['perturbation']
    delta_xyz = np.array([
        np.random.uniform(-mag['x'], mag['x']),
        np.random.uniform(-mag['y'], mag['y']),
        np.random.uniform(-mag['z'], mag['z']),
    ])

    ang = cfg.get('angular_perturbation', {'roll': 5.0, 'pitch': 5.0, 'yaw': 5.0})
    delta_rpy = np.array([
        np.random.uniform(-ang['roll'], ang['roll']),
        np.random.uniform(-ang['pitch'], ang['pitch']),
        np.random.uniform(-ang['yaw'], ang['yaw']),
    ])

    delta_quat = euler_to_quat(*np.radians(delta_rpy))

    return delta_xyz, delta_quat, delta_rpy


# ----------------------------------------------------------------------------
# Node
# ----------------------------------------------------------------------------

class CloudManager(Node):

    def __init__(self, config, args):

        super().__init__('cloud_manager')

        self.cfg = config
        self.args = args

        self.tf_buffer = Buffer()
        self.tf_listener = TransformListener(self.tf_buffer, self)

        self.collecting = False
        self.frames = []
        self.received = 0

        # Latest merged output, published continuously.
        self.outputs = {}
        self.outputs_lock = threading.Lock()
        self.busy = threading.Lock()

        self.create_subscription(
            PointCloud2,
            config['cloud_topic'],
            self.on_cloud,
            RELIABLE_QOS,
        )

        # Publishers: one per view plus the merged cloud.
        names = [f'view_{k}' for k in range(int(config['num_views']))] + ['merged']
        self.cloud_publishers = {
            name: self.create_publisher(PointCloud2, f'/multiview/{name}', 1)
            for name in names
        }

        self.create_timer(1.0, self.publish)

        # The service blocks (arm motion, settling), so it gets its own
        # callback group; otherwise it would starve the cloud subscription
        # and the ArmMover callbacks that live in the default group.
        self.create_service(
            Trigger,
            '/multiview/capture',
            self.on_capture_service,
            callback_group=MutuallyExclusiveCallbackGroup(),
        )

        self.get_logger().info(
            'Ready. Call /multiview/capture (std_srvs/srv/Trigger) to capture and merge.'
        )

        self.pose_client = self.create_client(
            SendPose,
            'send_pose',
        )
    def wait_for_services(self, timeout=30.0):

        self.get_logger().info('Waiting for ArmServices...')

        if not self.pose_client.wait_for_service(timeout_sec=timeout):
            self.get_logger().error('/send_pose service is unavailable.')
            return False

        self.get_logger().info('/send_pose is available.')

        return True


    def wait_for_future(self, future, timeout=180.0):

        deadline = time.monotonic() + timeout

        while rclpy.ok() and not future.done():

            if time.monotonic() >= deadline:
                self.get_logger().error('Timed out waiting for /send_pose.')
                return None

            time.sleep(0.01)

        if not future.done():
            return None

        try:
            return future.result()

        except Exception as exc:
            self.get_logger().error(f'/send_pose call failed: {exc}')
            return None


    def move_to(self, pose):

        request = SendPose.Request()

        request.pose.position.x = float(pose[0])
        request.pose.position.y = float(pose[1])
        request.pose.position.z = float(pose[2])

        request.pose.orientation.x = float(pose[3])
        request.pose.orientation.y = float(pose[4])
        request.pose.orientation.z = float(pose[5])
        request.pose.orientation.w = float(pose[6])

        self.get_logger().info(
            f'Moving to pose: {np.round(pose, 4).tolist()}'
        )

        future = self.pose_client.call_async(request)

        response = self.wait_for_future(future)

        if response is None or not response.success:
            self.get_logger().error('Pose motion failed.')
            return False

        self.get_logger().info('Pose motion completed successfully.')

        return True
    # -- subscription / publishing -------------------------------------------

    def on_cloud(self, msg):

        self.received += 1

        if self.collecting and len(self.frames) < self.cfg['frames_per_view']:
            self.frames.append(msg)

    def publish(self):

        with self.outputs_lock:
            outputs = dict(self.outputs)

        if not outputs:
            return

        stamp = self.get_clock().now().to_msg()

        for name, points in outputs.items():
            if name in self.cloud_publishers:
                self.cloud_publishers[name].publish(
                    numpy_to_msg(points, None, self.args.frame, stamp)
                )

    # -- service ---------------------------------------------------------------

    def on_capture_service(self, request, response):

        if not self.busy.acquire(blocking=False):
            response.success = False
            response.message = 'A capture is already in progress.'
            return response

        try:
            ok, message = self.run_capture_and_merge()
        except Exception as e:  # keep the node alive on unexpected errors
            self.get_logger().error(f'Capture failed with exception: {e}')
            ok, message = False, f'exception: {e}'
        finally:
            self.busy.release()

        response.success = ok
        response.message = message
        return response

    def run_capture_and_merge(self):

        log = self.get_logger()
        cfg = self.cfg

        num_views = int(cfg['num_views'])

        session = os.path.join(
            HERE,
            'captures',
            datetime.now().strftime('%Y%m%d_%H%M%S'),
        )

        if not self.wait_for_tf():
            return False, 'TF not available'

        os.makedirs(session)

        # Obtain the current EE pose from TF.
        try:
            tf = self.tf_buffer.lookup_transform(
                cfg['base_frame'],
                cfg['ee_link'],
                Time(),
                timeout=Duration(seconds=2.0),
            )

        except TransformException as e:
            log.error(f"Could not obtain initial end-effector pose: {e}")
            return False, 'could not obtain initial end-effector pose'

        t = tf.transform.translation
        q = tf.transform.rotation

        current_pose = np.array([t.x, t.y, t.z, q.x, q.y, q.z, q.w])

        log.info(
            f"Starting at current EE pose: "
            f"{np.round(current_pose, 4).tolist()}"
        )

        # Capture views.

        for k in range(num_views):

            # First view: current position.
            # Remaining views: random perturbation from previous position.

            if k > 0:

                delta_xyz, delta_quat, delta_rpy = generate_perturbation(cfg)

                target = current_pose.copy()

                target[:3] += delta_xyz
                # Rotate about the end-effector's own axes.
                target[3:] = quat_multiply(current_pose[3:], delta_quat)

                log.info(
                    f"View {k}: perturbation "
                    f"dx={delta_xyz[0]:+.4f}, "
                    f"dy={delta_xyz[1]:+.4f}, "
                    f"dz={delta_xyz[2]:+.4f} m, "
                    f"droll={delta_rpy[0]:+.2f}, "
                    f"dpitch={delta_rpy[1]:+.2f}, "
                    f"dyaw={delta_rpy[2]:+.2f} deg"
                )

                log.info(f"Moving to: {np.round(target, 4).tolist()}")

                if not self.move_to(target):
                    log.error(f"Failed to reach view {k}.")
                    return False, f'failed to reach view {k}'

                current_pose = target

            else:

                log.info("View 0: capturing at the current robot position.")

            result = self.capture()

            if result is None:
                return False, f'no cloud captured for view {k}'

            points, colors, T = result

            save_cloud(
                os.path.join(session, f'view_{k}.npz'),
                points,
                colors,
                T_base_camera=T,
                target=current_pose,
            )

            log.info(
                f"View {k}: saved {len(points)} points "
                f"(camera at "
                f"x={T[0, 3]:.3f}, "
                f"y={T[1, 3]:.3f}, "
                f"z={T[2, 3]:.3f} "
                f"in {cfg['base_frame']})"
            )

        log.info(f"Successfully captured {num_views} views.")
        log.info("Leaving robot at its final position (no homing).")

        # Merge.
        return self.merge_session(session)

    # -- merge (from merge_views.py main) -------------------------------------

    def merge_session(self, session):

        log = self.get_logger()
        args = self.args

        import glob
        files = sorted(glob.glob(os.path.join(session, 'view_*.npz')),
                       key=lambda f: int(os.path.basename(f)[5:-4]))

        if len(files) < 2:
            msg = f'Need at least two view_*.npz files in {session}.'
            log.error(msg)
            return False, msg

        views = [load_cloud(f)[0] for f in files]
        log.info(f'Loaded {len(views)} views from {session}: '
                 + ', '.join(str(len(p)) for p in views) + ' points')

        if not args.keep_outliers:
            views = [remove_outliers(p) for p in views]
            log.info('After outlier removal: '
                     + ', '.join(str(len(p)) for p in views) + ' points')

        outputs = {f'view_{k}': view for k, view in enumerate(views)}

        if not args.no_icp:
            target_points = views[0]
            aligned = [views[0]]
            for k, points in enumerate(views[1:], start=1):
                T, report = refine_with_icp(points, target_points, args.icp_voxel, args.icp_distance)
                log.info(f'ICP view {k} -> view 0: {report}')
                aligned.append(PointCloud(points).transform(T).xyz)
            final = merge(aligned, args.voxel)
        else:
            final = merge(views, args.voxel)

        outputs['merged'] = final
        save_cloud(os.path.join(session, 'merged.npz'), final)
        log.info(f'Saved merged cloud ({len(final)} points) to {session}/merged.npz')

        # Swap in the new result; the timer keeps publishing it.
        with self.outputs_lock:
            self.outputs = outputs

        return True, f'merged {len(final)} points ({session})'

    # -- capture (unchanged from capture_views.py) -----------------------------

    def wait_for_tf(self, timeout=15.0):

        child = self.cfg['hand_eye']['child']
        deadline = time.time() + timeout

        while time.time() < deadline:

            if self.tf_buffer.can_transform(
                self.cfg['base_frame'],
                child,
                Time(),
            ):
                return True

            time.sleep(0.2)

        self.get_logger().error(
            f"No TF {self.cfg['base_frame']} -> {child}: "
            "is bringup_robot.launch.py (and bringup_camera.launch.py) running?"
        )

        return False

    def capture(self):

        self.get_logger().info(
            f"Waiting {self.cfg['settle_time']:.1f} s for the arm to settle ..."
        )

        time.sleep(self.cfg['settle_time'])

        self.frames = []
        received_before = self.received

        self.collecting = True

        deadline = time.time() + 10.0

        while (
            len(self.frames) < self.cfg['frames_per_view']
            and time.time() < deadline
        ):
            time.sleep(0.02)

        self.collecting = False

        if not self.frames:

            if self.received == 0:
                why = (
                    'no cloud has arrived since this script started: '
                    f"is the camera publishing? (check: ros2 topic hz "
                    f"{self.cfg['cloud_topic']})"
                )

            elif self.received == received_before:
                why = (
                    'clouds arrived earlier but stopped: the camera '
                    'probably dropped off USB during the move'
                )

            else:
                why = 'clouds arrived but were not stored (unexpected)'

            self.get_logger().error(
                f"No clouds captured on {self.cfg['cloud_topic']}: {why}"
            )

            return None

        self.get_logger().info(f'Got {len(self.frames)} clouds')

        all_points = []
        all_colors = []
        T_first = None

        for msg in self.frames:

            try:
                tf = self.tf_buffer.lookup_transform(
                    self.cfg['base_frame'],
                    msg.header.frame_id,
                    Time.from_msg(msg.header.stamp),
                    timeout=Duration(seconds=0.5),
                )

            except TransformException:

                try:
                    tf = self.tf_buffer.lookup_transform(
                        self.cfg['base_frame'],
                        msg.header.frame_id,
                        Time(),
                        timeout=Duration(seconds=1.0),
                    )

                except TransformException as e:

                    self.get_logger().error(
                        f"TF {msg.header.frame_id} -> "
                        f"{self.cfg['base_frame']} failed: {e}"
                    )

                    return None

            T = transform_to_matrix(tf.transform)

            if T_first is None:
                T_first = T

            points, colors = msg_to_numpy(msg)
            # gz body convention (x fwd, y left, z up) -> optical (x right, y down, z fwd)
            if self.cfg.get('cloud_axes', 'optical') == 'gz_body':
                points = np.column_stack([-points[:, 1], -points[:, 2], points[:, 0]])

            max_depth = self.cfg.get('max_depth')

            if max_depth:

                near = points[:, 2] <= max_depth

                points = points[near]

                if colors is not None:
                    colors = colors[near]

            points, colors = crop_box(
                apply_transform(points, T),
                colors,
                self.cfg['workspace'],
            )

            all_points.append(points)

            if colors is not None:
                all_colors.append(colors)

        points = np.concatenate(all_points)

        colors = (
            np.concatenate(all_colors)
            if len(all_colors) == len(all_points)
            else None
        )

        return points, colors, T_first


def main():

    parser = argparse.ArgumentParser(
        description='Multi-view capture service + continuous merged cloud publisher'
    )

    # capture_views.py arguments
    parser.add_argument(
        '--config',
        default=os.path.join(CONFIG_DIR, 'views.yaml'),
        help='Per-robot YAML configuration',
    )
    parser.add_argument(
        '--settle',
        type=float,
        help='Seconds to wait at each view (overrides settle_time)',
    )
    parser.add_argument('--sim', action='store_true',
                        help='Gazebo cloud axes (x fwd, y left, z up) -> optical')

    # merge_views.py arguments
    parser.add_argument('--voxel', type=float, default=0.004, help='output voxel size in m (default 0.004)')
    parser.add_argument('--icp-voxel', type=float, default=0.004, help='voxel size used inside ICP (m)')
    parser.add_argument('--icp-distance', type=float, default=0.005,
                        help='final ICP correspondence distance in m; coarse stages use 4x and 2x (default 0.005)')
    parser.add_argument('--no-icp', action='store_true', help='TF-only merge')
    parser.add_argument('--keep-outliers', action='store_true', help='skip statistical outlier removal')
    parser.add_argument('--frame', default='base_link')

    args, _ = parser.parse_known_args()

    with open(args.config) as f:
        cfg = yaml.safe_load(f)

    if args.settle is not None:
        cfg['settle_time'] = args.settle
    if args.sim:
        cfg['cloud_axes'] = 'gz_body'

    # Validate configuration.

    num_views = int(cfg['num_views'])

    if num_views < 2:
        print('num_views must be at least 2 (merging needs two or more views).')
        return 1

    for axis in ('x', 'y', 'z'):

        if axis not in cfg['perturbation']:
            print(f'Missing perturbation magnitude for axis {axis}.')
            return 1

        if cfg['perturbation'][axis] < 0:
            print(f'Perturbation magnitude for {axis} must be nonnegative.')
            return 1

    ang_cfg = cfg.get('angular_perturbation', {})
    for axis in ('roll', 'pitch', 'yaw'):
        if ang_cfg.get(axis, 0.0) < 0:
            print(f'Angular perturbation for {axis} must be nonnegative.')
            return 1

    rclpy.init(args=None)

    node = CloudManager(cfg, args)

    executor = MultiThreadedExecutor(num_threads=4)
    executor.add_node(node)

    spinner = threading.Thread(
        target=executor.spin,
        daemon=True,
    )

    spinner.start()

    if not node.wait_for_services():
        executor.shutdown()
        spinner.join(timeout=2.0)
        node.destroy_node()
        rclpy.shutdown()
        return 1

    try:
        while rclpy.ok():
            time.sleep(0.5)
    except KeyboardInterrupt:
        pass
    finally:
        executor.shutdown()
        spinner.join(timeout=2.0)
        node.destroy_node()
        if rclpy.ok():
            rclpy.shutdown()

    return 0


if __name__ == '__main__':
    sys.exit(main())